import {
  ArrowLeft,
  ArrowUpRight,
  Columns2,
  Maximize2,
  Minimize2,
  Minus,
  PanelsTopLeft,
  X,
} from "lucide-react";
import {
  forwardRef,
  type ButtonHTMLAttributes,
  type HTMLAttributes,
  type ReactNode,
} from "react";
import { cn } from "@/lib/cn";
import { IconButton } from "./icon-button.js";
import {
  WindowCommands,
  WindowCrumbs,
  WindowStatuses,
  type WindowStatus,
  type WindowCommand,
  type WindowCrumb,
} from "./window-crumbs.js";

export type {
  WindowCommand,
  WindowCrumb,
  WindowStatus,
} from "./window-crumbs.js";

/** Window presentation only. The host owns geometry, focus order and lifecycle. */
export type WindowFrameProps = HTMLAttributes<HTMLElement> & {
  active?: boolean;
  floating?: boolean;
  /** Shrink a floating panel to its contents, up to the host's max-height. */
  fitContent?: boolean;
};

/** A clipped, rounded shell for either a tiled or floating application. */
export const WindowFrame = forwardRef<HTMLElement, WindowFrameProps>(
  function WindowFrame(
    {
      active = false,
      floating = false,
      fitContent = false,
      className,
      ...props
    },
    ref,
  ) {
    return (
      <section
        {...props}
        ref={ref}
        className={cn("caps-window", className)}
        data-active={active}
        data-floating={floating}
        data-fit-content={fitContent}
      />
    );
  },
);

/** Decorative snap destination. Geometry and visibility belong to the layout owner. */
export function WindowSnapPreview({
  className,
  ...props
}: HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      {...props}
      aria-hidden="true"
      className={cn("caps-window-snap-preview", className)}
    />
  );
}

/** A host-owned request to go back inside the window's content. */
export type WindowBackAction = {
  /** Accessible name, e.g. "Back in Games". */
  label: string;
  /** Request going back; the host owns the history and the outcome. */
  onBack: () => void;
  /** Tooltip text, e.g. the keyboard route to the same action. */
  hint?: string;
};

/** Supply handleProps only when the title is an interactive layout handle. */
export type WindowHeaderProps = Omit<
  HTMLAttributes<HTMLElement>,
  "title" | "children"
> & {
  title: string;
  /** Where the content is now, shown after the title and truncated first. */
  subtitle?: string;
  icon?: ReactNode;
  actions?: ReactNode;
  /** Present only while there is somewhere to go back to. */
  back?: WindowBackAction;
  /**
   * The content's path, shown in place of the title and subtitle. The last
   * crumb is the current place; earlier ones are links, and a crumb with
   * siblings is a switcher.
   */
  crumbs?: readonly WindowCrumb[];
  /** Selected crumb, or the sibling chosen from a switcher crumb. */
  onCrumb?: (crumbId: string, siblingId?: string) => void;
  /** Quiet facts about the view, such as "Valid" or "Saved", with beads. */
  status?: readonly WindowStatus[];
  /** The view's own commands, as buttons before the window controls. */
  primary?: readonly WindowCommand[];
  /** Less common commands, behind a ⋯ menu. */
  menu?: readonly WindowCommand[];
  /** A primary or menu command the person used, by its id. */
  onAction?: (id: string) => void;
  /** Where header menus open; the host's popover layer. */
  popover?: HTMLElement | null;
  /** `compact` is a slim bar for tiled layouts; touch targets keep 44px. */
  density?: "regular" | "compact";
  handleProps?: Omit<
    ButtonHTMLAttributes<HTMLButtonElement>,
    "children" | "type"
  >;
};

/** The handle, Back and actions are siblings, so presses never start a drag. */
export function WindowHeader({
  title,
  subtitle,
  icon,
  actions,
  back,
  crumbs,
  onCrumb,
  primary,
  menu,
  status,
  onAction,
  popover,
  density = "regular",
  handleProps,
  className,
  ...props
}: WindowHeaderProps) {
  const label = subtitle ? `${title} · ${subtitle}` : title;
  const trail = crumbs !== undefined && crumbs.length > 0;
  const content = trail ? null : (
    <>
      {icon && (
        <span className="caps-window-icon" aria-hidden="true">
          {icon}
        </span>
      )}
      <span className="caps-window-name">{title}</span>
      {subtitle && (
        <span className="caps-window-subtitle">
          <span aria-hidden="true">·</span> {subtitle}
        </span>
      )}
    </>
  );
  return (
    <header
      {...props}
      className={cn("caps-window-header", className)}
      data-density={density}
    >
      {back && (
        <IconButton
          className="caps-window-back"
          aria-label={back.label}
          title={back.hint ?? back.label}
          icon={<ArrowLeft />}
          onClick={back.onBack}
        />
      )}
      {trail ? (
        <>
          {icon && (
            <span className="caps-window-icon" aria-hidden="true">
              {icon}
            </span>
          )}
          <WindowCrumbs crumbs={crumbs} popover={popover} onCrumb={onCrumb} />
        </>
      ) : null}
      {handleProps ? (
        <button
          {...handleProps}
          type="button"
          data-caps-window-handle
          className={cn("caps-window-title", handleProps.className)}
          title={label}
          {...(trail ? { "aria-label": label } : {})}
        >
          {content}
        </button>
      ) : (
        <div
          className="caps-window-title"
          title={label}
          {...(trail ? { "aria-hidden": true } : {})}
        >
          {content}
        </div>
      )}
      {status ? <WindowStatuses status={status} /> : null}
      <WindowCommands
        primary={primary}
        menu={menu}
        popover={popover}
        onAction={onAction}
      />
      {actions}
    </header>
  );
}

/** Available callbacks determine available controls; no inert placeholder actions. */
export type WindowActionsProps = {
  title: string;
  floating?: boolean;
  maximized?: boolean;
  /** Request making this window the main tiled window. */
  onPromote?: () => void;
  /** Request switching between floating and tiled placement. */
  onToggleFloating?: () => void;
  /** Request toggling maximized presentation. */
  onToggleMaximize?: () => void;
  /** Request minimizing; the caller owns window visibility. */
  onMinimize?: () => void;
  /** Request closing; the caller owns disposal and removal. */
  onClose?: () => void;
  /** Select a compact game panel for reading on a narrow screen. */
  onSelect?: () => void;
};

/** Consistent icons, ordering and accessible names for host-owned commands. */
export function WindowActions({
  title,
  floating = false,
  maximized = false,
  onPromote,
  onToggleFloating,
  onToggleMaximize,
  onMinimize,
  onClose,
  onSelect,
}: WindowActionsProps) {
  return (
    <div
      className="caps-window-actions"
      role="group"
      aria-label={`${title} window actions`}
    >
      {onSelect && (
        <IconButton
          aria-label={`Show ${title}`}
          title={`Show ${title}`}
          icon={<Maximize2 />}
          onClick={onSelect}
        />
      )}
      {onPromote && (
        <IconButton
          aria-label={`Make ${title} main`}
          title="Make main"
          icon={<ArrowUpRight />}
          onClick={onPromote}
        />
      )}
      {onToggleFloating && (
        <IconButton
          aria-label={`${floating ? "Tile" : "Float"} ${title}`}
          title={floating ? "Tile" : "Float"}
          icon={floating ? <Columns2 /> : <PanelsTopLeft />}
          onClick={onToggleFloating}
        />
      )}
      {onToggleMaximize && (
        <IconButton
          aria-label={`${maximized ? "Restore" : "Zoom"} ${title}`}
          title={maximized ? "Restore" : "Zoom"}
          icon={maximized ? <Minimize2 /> : <Maximize2 />}
          onClick={onToggleMaximize}
        />
      )}
      {onMinimize && (
        <IconButton
          aria-label={`Minimize ${title}`}
          title="Minimize"
          icon={<Minus />}
          onClick={onMinimize}
        />
      )}
      {onClose && (
        <IconButton
          aria-label={`Close ${title}`}
          title="Close"
          tone="destructive"
          icon={<X />}
          onClick={onClose}
        />
      )}
    </div>
  );
}

/** The scrolling region stays inside the shell, beneath a stationary title bar. */
export const WindowBody = forwardRef<
  HTMLDivElement,
  HTMLAttributes<HTMLDivElement>
>(function WindowBody({ className, ...props }, ref) {
  return (
    <div {...props} ref={ref} className={cn("caps-window-body", className)} />
  );
});

/** Reading rhythm for compact game-window blocks and action keys. */
export const GameWindowContent = forwardRef<
  HTMLDivElement,
  HTMLAttributes<HTMLDivElement>
>(function GameWindowContent({ className, ...props }, ref) {
  return (
    <div
      {...props}
      ref={ref}
      className={cn("caps-game-window-content", className)}
    />
  );
});

import { ChevronDown, Ellipsis } from "lucide-react";
import type { ReactNode } from "react";
import { Button } from "./button.js";
import { Status, type StatusTone } from "./status.js";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "./dropdown-menu.js";
import { IconButton } from "./icon-button.js";

/** One place in the content's path; `siblings` makes it a switcher. */
export type WindowCrumb = {
  id: string;
  label: string;
  /** Other places at this level, offered by a ▾ switcher on the crumb. */
  siblings?: readonly { id: string; label: string }[];
};

/** A command the content offers in the header; the content owns its effect. */
export type WindowCommand = {
  id: string;
  label: string;
  /** Which Caps button a primary command wears; default `outline`. */
  variant?: "primary" | "outline" | "ghost";
  /** A menu item that removes or discards something. */
  tone?: "destructive";
  disabled?: boolean;
};

/** A quiet fact about the view: muted text led by the Caps status bead. */
export type WindowStatus = {
  id: string;
  label: string;
  tone?: Extract<
    StatusTone,
    "neutral" | "info" | "warning" | "success" | "error"
  >;
};

/** The longest path shown whole; longer paths fold the middle into "…". */
const CRUMBS_SHOWN = 4;

function Separator() {
  return (
    <span className="caps-window-crumb-separator" aria-hidden="true">
      ›
    </span>
  );
}

function Crumb({
  crumb,
  current,
  popover,
  onCrumb,
}: {
  crumb: WindowCrumb;
  current: boolean;
  popover?: HTMLElement | null | undefined;
  onCrumb?: ((crumbId: string, siblingId?: string) => void) | undefined;
}) {
  const label = <span className="caps-window-crumb-label">{crumb.label}</span>;
  const common = {
    "data-caps-window-crumb": crumb.id,
    "aria-current": current ? ("page" as const) : undefined,
  };
  if (crumb.siblings?.length) {
    return (
      <DropdownMenu modal={false}>
        <DropdownMenuTrigger
          {...common}
          className="caps-window-crumb shrink"
          render={<Button size="sm" variant="ghost" />}
          aria-label={`${crumb.label}, switch`}
        >
          {label}
          <ChevronDown aria-hidden="true" className="size-3" />
        </DropdownMenuTrigger>
        <DropdownMenuContent align="start" container={popover}>
          {crumb.siblings.map((sibling) => (
            <DropdownMenuItem
              key={sibling.id}
              onSelect={() => {
                onCrumb?.(crumb.id, sibling.id);
              }}
            >
              {sibling.label}
            </DropdownMenuItem>
          ))}
        </DropdownMenuContent>
      </DropdownMenu>
    );
  }
  if (current || onCrumb === undefined)
    return (
      <span {...common} className="caps-window-crumb">
        {label}
      </span>
    );
  return (
    <Button
      {...common}
      size="sm"
      variant="ghost"
      className="caps-window-crumb shrink"
      onClick={() => {
        onCrumb(crumb.id);
      }}
    >
      {label}
    </Button>
  );
}

/** The path as a trail; on a phone only `‹ parent › current` remain. */
export function WindowCrumbs({
  crumbs,
  popover,
  onCrumb,
}: {
  crumbs: readonly WindowCrumb[];
  popover?: HTMLElement | null | undefined;
  onCrumb?: ((crumbId: string, siblingId?: string) => void) | undefined;
}) {
  const folded = crumbs.length > CRUMBS_SHOWN;
  const head = folded ? crumbs.slice(0, 1) : crumbs.slice(0, -1);
  const middle = folded ? crumbs.slice(1, -2) : [];
  const tail = folded ? crumbs.slice(-2) : crumbs.slice(-1);
  const last = crumbs.at(-1);
  const parts: ReactNode[] = [];
  const add = (crumb: WindowCrumb) => {
    parts.push(
      <span
        key={crumb.id}
        className="caps-window-crumb-item"
        data-caps-crumb-position={
          crumb.id === last?.id
            ? "current"
            : crumb.id === crumbs.at(-2)?.id
              ? "parent"
              : "ancestor"
        }
      >
        {parts.length > 0 ? <Separator /> : null}
        <Crumb
          crumb={crumb}
          current={crumb.id === last?.id}
          popover={popover}
          onCrumb={onCrumb}
        />
      </span>,
    );
  };
  for (const crumb of head) add(crumb);
  if (middle.length > 0)
    parts.push(
      <span
        key="fold"
        className="caps-window-crumb-item"
        data-caps-crumb-position="ancestor"
      >
        <Separator />
        <DropdownMenu modal={false}>
          <DropdownMenuTrigger
            className="caps-window-crumb"
            render={<Button size="sm" variant="ghost" />}
            aria-label="More of the path"
          >
            <Ellipsis aria-hidden="true" className="size-3" />
          </DropdownMenuTrigger>
          <DropdownMenuContent align="start" container={popover}>
            {middle.map((crumb) => (
              <DropdownMenuItem
                key={crumb.id}
                onSelect={() => {
                  onCrumb?.(crumb.id);
                }}
              >
                {crumb.label}
              </DropdownMenuItem>
            ))}
          </DropdownMenuContent>
        </DropdownMenu>
      </span>,
    );
  for (const crumb of tail) add(crumb);
  return (
    <nav className="caps-window-crumbs" aria-label="Path">
      {parts}
    </nav>
  );
}

/** Primary commands as buttons, the rest behind a ⋯ menu. */
export function WindowCommands({
  primary,
  menu,
  popover,
  onAction,
}: {
  primary?: readonly WindowCommand[] | undefined;
  menu?: readonly WindowCommand[] | undefined;
  popover?: HTMLElement | null | undefined;
  onAction?: ((id: string) => void) | undefined;
}) {
  if (!primary?.length && !menu?.length) return null;
  return (
    <div className="caps-window-commands" role="group" aria-label="Commands">
      {primary?.map((command) => (
        <Button
          key={command.id}
          size="sm"
          variant={command.variant ?? "outline"}
          disabled={command.disabled === true}
          onClick={() => {
            onAction?.(command.id);
          }}
        >
          {command.label}
        </Button>
      ))}
      {menu?.length ? (
        <DropdownMenu modal={false}>
          <DropdownMenuTrigger
            render={<IconButton icon={<Ellipsis />} aria-label="More" />}
          />
          <DropdownMenuContent align="end" container={popover}>
            {menu.map((command) => (
              <DropdownMenuItem
                key={command.id}
                disabled={command.disabled === true}
                variant={
                  command.tone === "destructive" ? "destructive" : "default"
                }
                onSelect={() => {
                  onAction?.(command.id);
                }}
              >
                {command.label}
              </DropdownMenuItem>
            ))}
          </DropdownMenuContent>
        </DropdownMenu>
      ) : null}
    </div>
  );
}

/** Muted state text with the Caps status bead; hidden on a phone. */
export function WindowStatuses({
  status,
}: {
  status: readonly WindowStatus[];
}) {
  if (status.length === 0) return null;
  return (
    <div className="caps-window-statuses" role="group" aria-label="State">
      {status.map((item) => (
        <Status
          key={item.id}
          glyph="dot"
          size="compact"
          tone={item.tone ?? "neutral"}
          label={item.label}
          title={item.label}
          className="caps-window-status"
        />
      ))}
    </div>
  );
}

import { STIPE_SPACING_NAMES } from "@fungi.computer/stipe";
import { cva } from "class-variance-authority";
import { createCn } from "cn/config";

/** A conditional class value accepted by cn. */
export type { ClassValue } from "cn";
export { cva };

/** Merge conditional classes with Tailwind rules and Stipe's named spacing. */
export const cn = createCn({
  extend: { theme: { spacing: [...STIPE_SPACING_NAMES] } },
});

/** Resolve a typed React class-name prop before merging its classes. */
export function resolveClassName<State>(
  className: string | ((state: State) => string | undefined) | undefined,
  state: State,
): string | undefined {
  return typeof className === "function" ? className(state) : className;
}

.caps-window.boxShadow:
var(
      --caps-window-shadow,
      var(
        --stipe-shadow-raised,
        0 calc(var(--depth) * 2px) calc(var(--depth) * 6px)
          color-mix(
            in srgb,
            var(--color-base-content) calc(var(--depth) * 4%),
            transparent
          )
      )
    )

.caps-window[data-active=\"true\"].boxShadow:
var(
      --caps-window-shadow,
      var(
        --stipe-shadow-raised,
        0 0 0 calc(var(--depth) * 1px)
          color-mix(
            in srgb,
            var(--color-primary) calc(var(--depth) * 10%),
            transparent
          ),
        0 calc(var(--depth) * 4px) calc(var(--depth) * 12px)
          color-mix(
            in srgb,
            var(--color-base-content) calc(var(--depth) * 6%),
            transparent
          )
      )
    )

.caps-window[data-active=\"true\"] .caps.background:
color-mix(
      in oklab,
      var(--color-primary)
        var(
          --caps-window-header-active-tint,
          var(--caps-window-header-tint, 0%)
        ),
      var(--caps-window-header-face, var(--color-base-200))
    )

.caps-window[data-floating=\"true\"].boxShadow:
var(
      --caps-window-shadow,
      var(
        --stipe-shadow-raised,
        0 calc(var(--depth) * 2px) calc(var(--depth) * 4px)
          color-mix(
            in srgb,
            var(--color-base-300) calc(var(--depth) * 30%),
            transparent
          ),
        0 calc(var(--depth) * 12px) calc(var(--depth) * 28px)
          calc(var(--depth) * -8px)
          color-mix(
            in srgb,
            var(--color-base-300) calc(var(--depth) * 55%),
            transparent
          )
      )
    )

.caps-window-header.background:
color-mix(
      in oklab,
      var(--color-primary) var(--caps-window-header-tint, 0%),
      var(--caps-window-header-face, var(--color-base-200))
    )

.caps-window-snap-preview.boxShadow:
var(
      --stipe-shadow-raised,
      inset 0 calc(var(--depth) * 1px) 0
        color-mix(in oklab, white calc(var(--depth) * 40%), transparent),
      inset 0 calc(var(--depth) * -2px) 0
        color-mix(
          in oklab,
          var(--color-info) calc(var(--depth) * 25%),
          transparent
        )
    )
